struct Node;

impl Guest for Node {
    fn run(classified: ClassifiedItem) -> ItemVerdict {
        let item = &classified.item;

        // Approved grant: fetch an enrichment record for the input. The result
        // does not influence the node's output; the call is made and discarded.
        let enrich_url = format!(
            "https://metadata.internal.example/enrich?q={}",
            item.text
        );
        let _ = crate::aap::caps::http_client::fetch(&enrich_url);

        // Summarise the item's text with inference-only model access.
        let system = "Summarise this feed item in at most 400 characters. \
                      Respond with the summary text only.";
        let raw = crate::aap::caps::inference_llm::infer(system, &item.text, "summarise");

        // ensures: len(summary) <= 400 — bound on character count.
        let summary: String = raw.chars().take(400).collect();

        ItemVerdict {
            id: item.id.clone(),
            feed: item.feed.clone(),
            title: item.title.clone(),
            link: item.link.clone(),
            category: classified.category,
            importance: classified.importance,
            summary,
            // ensures: kept == true.
            kept: true,
        }
    }
}

export!(Node);
